definition.script:
pipeline {
    agent any

    environment {
        APP_NAME     = 'flaky-app'
        DEPLOY_DIR   = '/workspace/deploy'
        NOTIFY_SCRIPT = '/usr/local/bin/notify.sh'
    }

    stages {

        stage('Build') {
            steps {
                echo 'Building application...'
                sh '''
                    mkdir -p /workspace/build
                    echo "build-artifact-v1.0" > /workspace/build/artifact.txt
                    echo "[Build] Artifact created at /workspace/build/artifact.txt"
                '''
            }
        }

        stage('Test') {
            steps {
                // BUG 1: catchError masks the test failure.
                // buildResult stays SUCCESS even when flaky_test.sh exits 1,
                // so the pipeline continues and Deploy always runs.
                catchError(buildResult: 'SUCCESS', stageResult: 'FAILURE') {
                    sh '/usr/local/bin/flaky_test.sh'
                }
            }
        }

        stage('Approve') {
            when {
                // BUG 2: `not` inverts the condition.
                // Approval is currently required on every branch EXCEPT main.
                // Should be: when { branch 'main' }
                not {
                    branch 'main'
                }
            }
            steps {
                input message: 'Approve deployment to production?',
                      ok: 'Deploy'
            }
        }

        stage('Deploy') {
            // BUG 3: No when condition here.
            // Deploy runs unconditionally regardless of Test result.
            // Should guard with: when { expression { currentBuild.result != 'FAILURE' } }
            steps {
                echo 'Deploying application...'
                sh '''
                    mkdir -p /workspace/deploy
                    cp /workspace/build/artifact.txt /workspace/deploy/artifact.txt
                    echo "DEPLOYED" > /workspace/deploy/status.txt
                    echo "[Deploy] Artifact deployed to /workspace/deploy"
                '''
            }
        }

    }

    post {
        // BUG 4: Only success is handled.
        // The team receives no notification when the pipeline fails.
        success {
            sh "${NOTIFY_SCRIPT} success"
        }
        // Missing: failure block
    }
}
